var SHINAYUU_V6_UI_TEXT={"ShinaYuu Music là trình phát nhạc trực quan":["ShinaYuu Music là trình phát nhạc trực quan","ShinaYuu Music is a visual music player"],"Đây không chỉ là trang playlist: sau khi tìm hoặc nhập một bài hát, ảnh bìa, lời bài hát, hạt và máy quay sẽ chuyển động theo nhạc.":["Đây không chỉ là trang playlist: sau khi tìm hoặc nhập một bài hát, ảnh bìa, lời bài hát, hạt và máy quay sẽ chuyển động theo nhạc.","This is more than a playlist page: after searching for or importing a track, the cover, lyrics, particles, and camera move with the music."],"Bắt đầu bằng tìm kiếm hoặc nhập nhạc":["Bắt đầu bằng tìm kiếm hoặc nhập nhạc","Start with search or import"],"Nhập tên bài hát, nghệ sĩ hoặc từ khóa để phát; nhạc cục bộ có thể được đưa thẳng lên sân khấu qua mục Nhập.":["Nhập tên bài hát, nghệ sĩ hoặc từ khóa để phát; nhạc cục bộ có thể được đưa thẳng lên sân khấu qua mục Nhập.","Enter a song, artist, or keyword to play; local music can be placed directly on the stage through Import."],"Điều khiển phát nằm ở phía dưới":["Điều khiển phát nằm ở phía dưới","Playback controls are at the bottom"],"Phát, chuyển bài, tiến độ, hàng chờ và lời bài hát đều nằm ở thanh dưới; bạn có thể sử dụng như một trình phát nhạc thông thường.":["Phát, chuyển bài, tiến độ, hàng chờ và lời bài hát đều nằm ở thanh dưới; bạn có thể sử dụng như một trình phát nhạc thông thường.","Play, next, progress, queue, and lyrics are all in the bottom bar; use it like a normal music player."],"Đăng nhập chỉ để đồng bộ thư viện nhạc":["Đăng nhập chỉ để đồng bộ thư viện nhạc","Sign in only to sync your music library"],"Sau khi đăng nhập, playlist và bài yêu thích sẽ được đồng bộ; bạn vẫn có thể tìm và phát nhạc mà không cần đăng nhập.":["Sau khi đăng nhập, playlist và bài yêu thích sẽ được đồng bộ; bạn vẫn có thể tìm và phát nhạc mà không cần đăng nhập.","After signing in, playlists and liked tracks are synced; you can still search and play without signing in."],"Các công cụ hình ảnh nâng cao nằm quanh sân khấu":["Các công cụ hình ảnh nâng cao nằm quanh sân khấu","Advanced visual tools surround the stage"],"Kệ playlist 3D bên phải và chế độ DIY là các mục nâng cao; hãy phát một bài trước rồi điều chỉnh hiệu ứng.":["Kệ playlist 3D bên phải và chế độ DIY là các mục nâng cao; hãy phát một bài trước rồi điều chỉnh hiệu ứng.","The 3D playlist shelf and DIY mode are advanced tools; play a track first, then tune the effects."],"Tính năng nâng cao nằm trong chế độ DIY":["Tính năng nâng cao nằm trong chế độ DIY","Advanced features are in DIY mode"],"Bảng điều khiển hình ảnh, nhập nhạc/ảnh bìa, lời tùy chỉnh, chất lượng âm thanh và các bảng nâng cao sẽ xuất hiện tại đây.":["Bảng điều khiển hình ảnh, nhập nhạc/ảnh bìa, lời tùy chỉnh, chất lượng âm thanh và các bảng nâng cao sẽ xuất hiện tại đây.","The visual console, music/cover import, custom lyrics, audio quality, and advanced panels appear here."],"Đã mở chế độ DIY":["Đã mở chế độ DIY","DIY mode is open"],"Bạn có thể quay lại chế độ mặc định bất cứ lúc nào. Chế độ DIY hiển thị đầy đủ bảng điều khiển, nhập nội dung và các thiết lập nâng cao.":["Bạn có thể quay lại chế độ mặc định bất cứ lúc nào. Chế độ DIY hiển thị đầy đủ bảng điều khiển, nhập nội dung và các thiết lập nâng cao.","You can return to default mode at any time. DIY mode shows the full console, import tools, and advanced settings."],"Nguồn tìm kiếm và mục nhập sẽ được mở rộng":["Nguồn tìm kiếm và mục nhập sẽ được mở rộng","Search sources and import tools expand"],"Thanh tìm kiếm phía trên cho phép đổi nguồn; các mục nhập bài hát và ảnh bìa cũng được hiển thị trong chế độ DIY.":["Thanh tìm kiếm phía trên cho phép đổi nguồn; các mục nhập bài hát và ảnh bìa cũng được hiển thị trong chế độ DIY.","The top search bar can switch sources; music and cover import tools also appear in DIY mode."],"Playlist và hàng chờ đầy đủ nằm bên trái":["Playlist và hàng chờ đầy đủ nằm bên trái","Full playlists and queue are on the left"],"Di chuyển tới cạnh trái để mở bảng playlist/hàng chờ và quản lý hàng chờ, playlist cá nhân hoặc podcast.":["Di chuyển tới cạnh trái để mở bảng playlist/hàng chờ và quản lý hàng chờ, playlist cá nhân hoặc podcast.","Move to the left edge to open playlists/queue and manage the queue, personal playlists, or podcasts."],"Bảng điều khiển hình ảnh nằm bên phải":["Bảng điều khiển hình ảnh nằm bên phải","The visual console is on the right"],"Di chuyển tới góc phải dưới hoặc nhấn nút hình ảnh để chỉnh hạt, lời, máy quay, kệ playlist 3D và các thông số khác.":["Di chuyển tới góc phải dưới hoặc nhấn nút hình ảnh để chỉnh hạt, lời, máy quay, kệ playlist 3D và các thông số khác.","Move to the lower-right corner or select the visual button to adjust particles, lyrics, camera, the 3D shelf, and other settings."],"Điều khiển phát nâng cao sẽ được hiển thị đầy đủ":["Điều khiển phát nâng cao sẽ được hiển thị đầy đủ","Advanced playback controls are fully shown"],"Chất lượng âm thanh, thứ tự phát, yêu thích, nguồn lời và các nút nâng cao được hiển thị đầy đủ trong chế độ DIY.":["Chất lượng âm thanh, thứ tự phát, yêu thích, nguồn lời và các nút nâng cao được hiển thị đầy đủ trong chế độ DIY.","Audio quality, playback order, likes, lyric source, and advanced controls are fully shown in DIY mode."],"Tải chi tiết playlist thất bại. Hãy thử lại sau.":["Tải chi tiết playlist thất bại. Hãy thử lại sau.","Could not load playlist details. Try again later."],"Không tìm thấy playlist":["Không tìm thấy playlist","No playlists found"],"Nhấn để vào ShinaYuu Music":["Nhấn để vào ShinaYuu Music","Click to enter ShinaYuu Music"],"Chọn một chế độ phân tích nhịp điện ảnh":["Chọn một chế độ phân tích nhịp điện ảnh","Choose a cinematic beat analysis mode"],"Dùng cache":["Dùng cache","Use cache"],"Bắt đầu phân tích":["Bắt đầu phân tích","Start analysis"],"Khôi phục thao tác ShinaYuu Music":["Khôi phục thao tác ShinaYuu Music","Restore ShinaYuu Music interaction"],"Đang chuyển sang chế độ desktop toàn phần":["Đang chuyển sang chế độ desktop toàn phần","Switching to full desktop mode"],"ShinaYuu Music · Thư viện của bạn":["ShinaYuu Music · Thư viện của bạn","ShinaYuu Music · Your Library"],"Sử dụng dữ liệu gợi ý hiện tại của ShinaYuu Music":["Sử dụng dữ liệu gợi ý hiện tại của ShinaYuu Music","Use current ShinaYuu Music recommendation data"],"Gợi ý ShinaYuu Music":["Gợi ý ShinaYuu Music","ShinaYuu Music recommendation"],"Đầu ra ShinaYuu Music":["Đầu ra ShinaYuu Music","ShinaYuu Music output"],"Cài đặt phím tắt":["Cài đặt phím tắt","Hotkey settings"],"Trùng trong ShinaYuu Music":["Trùng trong ShinaYuu Music","Duplicate inside ShinaYuu Music"],"Chế độ desktop toàn phần":["Chế độ desktop toàn phần","Full desktop mode"],"Bản lưu người dùng ShinaYuu Music":["Bản lưu người dùng ShinaYuu Music","ShinaYuu Music user save"],"Mem Reduct chỉ chạy sau khi ShinaYuu Music được ẩn/thu nhỏ và đạt ngưỡng thời gian, bộ nhớ.":["Mem Reduct chỉ chạy sau khi ShinaYuu Music được ẩn/thu nhỏ và đạt ngưỡng thời gian, bộ nhớ.","Mem Reduct runs only after ShinaYuu Music is hidden/minimized and the time and memory thresholds are met."],"Giải phóng bộ nhớ hệ thống thủ công. ShinaYuu Music sẽ bỏ qua khi cửa sổ chính đang hiển thị để tránh tăng CPU.":["Giải phóng bộ nhớ hệ thống thủ công. ShinaYuu Music sẽ bỏ qua khi cửa sổ chính đang hiển thị để tránh tăng CPU.","Manual system memory release. ShinaYuu Music skips it while the main window is visible to avoid CPU spikes."],"Giải phóng nâng cao thủ công. Hãy thu nhỏ hoặc ẩn ShinaYuu Music trước để tránh tăng CPU.":["Giải phóng nâng cao thủ công. Hãy thu nhỏ hoặc ẩn ShinaYuu Music trước để tránh tăng CPU.","Manual elevated release. Minimize or hide ShinaYuu Music first to avoid CPU spikes."]};
