function apply(root){if(busy)return;busy=true;try{window.appLanguage=language;document.documentElement.lang=language;document.title="ShinaYuu Music";var scope=root&&root.nodeType?root:document.body;if(scope){if(scope.nodeType===3)translateNode(scope);else{var walker=document.createTreeWalker(scope,NodeFilter.SHOW_TEXT);var n;while((n=walker.nextNode()))translateNode(n);if(scope.nodeType===1)translateElement(scope);if(scope.querySelectorAll)Array.prototype.forEach.call(scope.querySelectorAll("*"),translateElement);}}var vi=document.getElementById("lang-vi-btn"),en=document.getElementById("lang-en-btn");if(vi){vi.classList.toggle("active",language==="vi");vi.setAttribute("aria-pressed",language==="vi"?"true":"false");}if(en){en.classList.toggle("active",language==="en");en.setAttribute("aria-pressed",language==="en"?"true":"false");}}finally{busy=false;}}
function setLanguage(next){language=next==="en"?"en":"vi";window.appLanguage=language;try{localStorage.setItem(STORE_KEY,language);}catch(_){}try{fetch("/api/providers/config",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({language:language})}).catch(function(){});}catch(_){}apply(document.body);["updateSearchModeTabs","updateLoginProviderUi","renderUserBtn","renderHomeDashboard"].forEach(function(name){try{if(typeof window[name]==="function")window[name]();}catch(_){}});try{if(typeof window.safeShelfRebuild==="function")window.safeShelfRebuild("language-change",true);}catch(_){}try{document.dispatchEvent(new CustomEvent("shinayuu-language-change",{detail:{language:language}}));}catch(_){}}
