function installControl(){
  var box=document.getElementById("shinayuu-language-control");
  if(!box){
    box=document.createElement("span");
    box.id="shinayuu-language-control";
    box.className="language-switch";
    box.setAttribute("role","group");
    box.setAttribute("aria-label","Ngôn ngữ / Language");
    box.innerHTML='<button id="lang-vi-btn" type="button" data-app-language="vi">VI</button><button id="lang-en-btn" type="button" data-app-language="en">EN</button>';
    var tabs=document.getElementById("search-mode-tabs");
    var searchStack=document.getElementById("search-stack");
    if(tabs)tabs.appendChild(box);else if(searchStack)searchStack.appendChild(box);else document.body.appendChild(box);
  }
  if(box.dataset.i18nBound!=="1"){
    box.dataset.i18nBound="1";
    box.addEventListener("click",function(e){
      var button=e.target&&e.target.closest?e.target.closest("[data-app-language]"):null;
      if(button)setLanguage(button.getAttribute("data-app-language"));
    });
  }
  var vi=document.getElementById("lang-vi-btn"),en=document.getElementById("lang-en-btn");
  if(vi){vi.setAttribute("aria-pressed",language==="vi"?"true":"false");vi.classList.toggle("active",language==="vi");}
  if(en){en.setAttribute("aria-pressed",language==="en"?"true":"false");en.classList.toggle("active",language==="en");}
}
